def generate(seed):
    r = random.Random(seed)
    def L(n):
        k = 0
        while n > 1:
            n = 3 * n + 1 if n % 2 else n // 2
            k += 1
        return k
    while True:
        k = L(r.randrange(2, 20000))
        if k >= 10 and L(k) != k:
            return str(k)

