def solve(clue):
    k = int(clue)
    memo = {1: 0}
    n = 2
    while n < 3000000:
        m, path = n, []
        while m not in memo:
            path.append(m)
            m = 3 * m + 1 if m % 2 else m // 2
        d = memo[m]
        for x in reversed(path):
            d += 1
            memo[x] = d
        if memo[n] == k:
            return str(n)
        n += 1
    return ''

